"""Hidden checks: the generator removes its own stale pages and nothing else; current pages are
(re)generated."""

import subprocess
import sys
from pathlib import Path

REPO = Path(__file__).resolve().parents[2]
SCRIPT = REPO / "scripts" / "gen_format_docs.py"
MARK = "<!-- generated by scripts/gen_format_docs.py"
CURRENT = {"csv_fmt", "html_table", "json_fmt", "md_table", "tsv_fmt", "xml_fmt", "yaml_fmt"}


def run(out):
    subprocess.run([sys.executable, str(SCRIPT), "--out", str(out)], check=True, capture_output=True, timeout=60)


def test_stale_generated_pages_go_and_hand_written_pages_stay(tmp_path):
    out = tmp_path / "formats"
    out.mkdir()
    (out / "old_fmt.md").write_text(f"{MARK} from textkit.formats.old_fmt; do not edit -->\n# old\n", encoding="utf-8")
    (out / "guide.md").write_text("# A guide\n\nWritten by hand, mentions csv_fmt.\n", encoding="utf-8")
    (out / "notes.txt").write_text("not a page\n", encoding="utf-8")
    (out / "md_table.md").write_text(f"{MARK} from textkit.formats.md_table; do not edit -->\nOLD\n", encoding="utf-8")
    run(out)
    names = {p.name for p in out.iterdir()}
    assert "old_fmt.md" not in names
    assert (out / "guide.md").read_text(encoding="utf-8") == "# A guide\n\nWritten by hand, mentions csv_fmt.\n"
    assert (out / "notes.txt").read_text(encoding="utf-8") == "not a page\n"
    assert {f"{name}.md" for name in CURRENT} <= names
    assert "OLD" not in (out / "md_table.md").read_text(encoding="utf-8")


def test_a_hand_written_page_named_like_a_removed_formatter_stays(tmp_path):
    out = tmp_path / "formats"
    out.mkdir()
    (out / "rst_table.md").write_text("# Why we dropped rst_table\n\nHand-written history.\n", encoding="utf-8")
    run(out)
    assert (out / "rst_table.md").read_text(encoding="utf-8").startswith("# Why we dropped rst_table")


def test_the_repository_docs_are_clean():
    pages = {p.stem for p in (REPO / "docs" / "formats").glob("*.md") if p.read_text(encoding="utf-8").startswith(MARK)}
    assert pages == CURRENT
